:root {
  --bg: #1e1e2f;
  --card-back: #2d2d44;
  --card-front: #f0f0f5;
  --accent: #f5a623;
  --text: #e0e0e0;
  --matched: #4caf50;
  --focus: #f5a623;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  max-width: 600px;
  width: 100%;
  text-align: center;
}

header {
  margin-bottom: 24px;
}

h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--accent);
}

.moves {
  font-size: 1.1rem;
  opacity: 0.9;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 24px;
}

.card {
  aspect-ratio: 1 / 1;
  background: var(--card-back);
  border-radius: 12px;
  cursor: pointer;
  position: relative;
  transition: transform 0.2s, background 0.2s;
  border: 3px solid transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  user-select: none;
  outline: none;
}

.card::before {
  content: '?';
  color: var(--text);
  opacity: 0.6;
}

.card.flipped {
  background: var(--card-front);
  cursor: default;
}

.card.flipped::before {
  content: '';
}

.card.matched {
  background: var(--matched);
  cursor: default;
  border-color: var(--accent);
}

.card:focus-visible {
  border-color: var(--focus);
  box-shadow: 0 0 0 4px rgba(245, 166, 35, 0.4);
}

.card:not(.flipped):not(.matched):hover {
  transform: scale(1.05);
  background: #3a3a55;
}

.card:not(.flipped):not(.matched):active {
  transform: scale(0.95);
}

.card .color-dot {
  width: 60%;
  height: 60%;
  border-radius: 50%;
  display: none;
}

.card.flipped .color-dot,
.card.matched .color-dot {
  display: block;
}

.win-message {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 16px;
}

#new-game {
  background: var(--accent);
  color: #1e1e2f;
  border: none;
  border-radius: 8px;
  padding: 14px 32px;
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

#new-game:hover {
  background: #ffb84d;
}

#new-game:active {
  transform: scale(0.96);
}

#new-game:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

@media (max-width: 480px) {
  .board {
    gap: 8px;
  }
  h1 {
    font-size: 1.6rem;
  }
  .card {
    border-radius: 8px;
  }
}

(function() {
  'use strict';

  const COLORS = ['#e74c3c', '#3498db', '#2ecc71', '#f1c40f', '#9b59b6', '#e67e22', '#1abc9c', '#e84393'];
  const board = document.getElementById('game-board');
  const moveCountEl = document.getElementById('move-count');
  const winMessage = document.getElementById('win-message');
  const newGameBtn = document.getElementById('new-game');

  let deck = [];
  let flipped = [];
  let matchedCount = 0;
  let moves = 0;
  let lock = false;

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function createDeck() {
    const pairs = [];
    COLORS.forEach((color, index) => {
      pairs.push({ color, pairId: index });
      pairs.push({ color, pairId: index });
    });
    return shuffle(pairs);
  }

  function renderBoard() {
    board.innerHTML = '';
    deck.forEach((cardData, i) => {
      const card = document.createElement('div');
      card.className = 'card';
      card.setAttribute('role', 'gridcell');
      card.setAttribute('tabindex', '0');
      card.setAttribute('aria-label', 'Hidden card');
      card.dataset.index = i;

      const dot = document.createElement('span');
      dot.className = 'color-dot';
      dot.style.backgroundColor = cardData.color;
      card.appendChild(dot);

      card.addEventListener('click', handleCardClick);
      card.addEventListener('keydown', handleKeyDown);
      board.appendChild(card);
    });
  }

  function handleKeyDown(e) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleCardClick.call(e.currentTarget);
    }
  }

  function handleCardClick() {
    if (lock) return;
    const card = this;
    if (card.classList.contains('flipped') || card.classList.contains('matched')) return;

    const index = parseInt(card.dataset.index, 10);
    const cardData = deck[index];

    card.classList.add('flipped');
    card.setAttribute('aria-label', 'Color card');
    flipped.push({ element: card, data: cardData });

    if (flipped.length === 2) {
      lock = true;
      moves++;
      moveCountEl.textContent = moves;
      checkMatch();
    }
  }

  function checkMatch() {
    const [first, second] = flipped;
    if (first.data.pairId === second.data.pairId) {
      first.element.classList.add('matched');
      second.element.classList.add('matched');
      first.element.setAttribute('aria-label', 'Matched card');
      second.element.setAttribute('aria-label', 'Matched card');
      matchedCount++;
      flipped = [];
      lock = false;
      if (matchedCount === COLORS.length) {
        winMessage.hidden = false;
      }
    } else {
      setTimeout(() => {
        first.element.classList.remove('flipped');
        second.element.classList.remove('flipped');
        first.element.setAttribute('aria-label', 'Hidden card');
        second.element.setAttribute('aria-label', 'Hidden card');
        flipped = [];
        lock = false;
      }, 800);
    }
  }

  function resetGame() {
    deck = createDeck();
    flipped = [];
    matchedCount = 0;
    moves = 0;
    lock = false;
    moveCountEl.textContent = '0';
    winMessage.hidden = true;
    renderBoard();
  }

  newGameBtn.addEventListener('click', resetGame);

  resetGame();
})();
